Section P1.
  Context {HCEIL : HeapCeil}.
  Variable H : asr.
  Hypothesis HHbp : asan_rt_hyps_bp H.
  Variables (ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 aw a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 : word)
            (F : bvmap 5 word) (fc : bv 32) (m0 : mem) (ds p pcons icount err lo : Z) (LF : list fframe).
  Hypothesis Ha0 : a0 = Z_to_bv 64 ds.
  Hypothesis Ha1 : a1 = Z_to_bv 64 p.
  Hypothesis Ha2 : a2 = Z_to_bv 64 (err mod 2 ^ 64).

  Hypothesis DSA : addressable m0 ds DS_SIZE.
  Hypothesis DSW : wr_at asegs m0 ds DS_SIZE.
  Hypothesis DSO : app_obj ds DS_SIZE.
  Hypothesis DS8 : ds mod 8 = 0.
  Hypothesis DSV : shvis m0 ds (ds + DS_SIZE).
  Hypothesis DSin : obj_inframe LF ds DS_SIZE.

  Hypothesis PCA : addressable m0 pcons 48.
  Hypothesis PCO : app_obj pcons 48.
  Hypothesis PC8 : pcons mod 8 = 0.
  Hypothesis PCC : rw_cells asegs m0 (pcons + 32) [C8 (Z_to_bv 64 0)].
  Hypothesis PCfs : fsobj H LF pcons 48.
  Hypothesis DISJ : forall a, ds <= a < ds + DS_SIZE -> ~ (pcons <= a < pcons + 48).
  Hypothesis ERR : - 2 ^ 31 <= err < 0.
  Hypothesis ICN : 0 <= icount < 2 ^ 63.
  Hypothesis PC16 : pcons mod 16 = 0.
  Hypothesis PPO : ds_obj H LF m0 (bv_unsigned sp) (p + 8) 8.
  Hypothesis PPC : ro_cells asegs m0 (p + 8) [C8 (Z_to_bv 64 pcons)].
  Hypothesis PIO : ds_obj H LF m0 (bv_unsigned sp) (p + 80) 8.
  Hypothesis PIC : ro_cells asegs m0 (p + 80) [C8 (Z_to_bv 64 icount)].

  Hypothesis STK : stk asegs m0 lo (bv_unsigned sp).
  Hypothesis CEIL : aceil <= lo.
  Hypothesis LO : lo <= bv_unsigned sp - ADS_STACK.
  Hypothesis SP16 : bv_unsigned sp mod 16 = 0.
  Hypothesis SPHI : bv_unsigned sp <= AAPP_HI.
  Hypothesis SPOBJ : forall O n, O = ds /\ n = DS_SIZE \/ O = pcons /\ n = 48 ->
                     O + n <= bv_unsigned sp - ADS_STACK \/ bv_unsigned sp <= O.

  Hypothesis MI0 : mem_inv asegs m0.
  Hypothesis AC0 : ACONST m0.
  Hypothesis LV0 : LINV_P5 m0.
  Hypothesis TP : tp = Z_to_bv 64 ATP.
  Hypothesis RFS0 : as_RFS H LF m0.
  Hypothesis LFn : (length LF < AFS_MAXLIVE_BP)%nat.
  Hypothesis THR : athr_cells m0.

  Notation spz := (bv_unsigned sp) (only parsing).

  Definition Wp0 : list word :=
    [Z_to_bv 64 ds; sp; ra; Z_to_bv 64 p; Z_to_bv 64 (err mod 2 ^ 64); aw; s0; s1; s2; s3; s4; s5; s6; s7; s8; s9; s10; s11; gp; tp].

  Definition P1w (m : mem) : Prop := munch [(spz - 8192, spz)] m0 m /\ wmono asegs m0 m.

  Lemma p1_ranges : 0 <= spz < 2 ^ 64 /\ aceil + ADS_STACK <= spz /\ 0x7fff7f800000 <= aceil <= 0x7fffff800000.
Proof.
    pose proof (bv_unsigned_in_range 64 sp) as R. change (bv_modulus 64) with (2 ^ 64) in R.
    pose proof aceil_facts as ((A1 & A2) & _).
    split; [lia|]. split; [lia|]. lia.
  Qed.

  Lemma p1_keep : forall m, P1w m -> mem_inv asegs m -> ACONST m /\ LINV_P5 m /\ stk asegs m lo spz.
Proof.
    intros m [MU WM] MI. pose proof p1_ranges as (R1 & R2 & R3). pose proof STK as (T1 & T2 & T3).
    split.
    { eapply ACONST_frame; [exact AC0 | exact MU | exact WM |].
      apply Forall_cons; [apply LbB_DPdK.aconst_ok_hi; unfold ADS_STACK in *; lia | apply Forall_nil]. }
    split.
    { eapply LINV_P5_cl; [exact LV0|]. intros a Ha Hc. unfold wa. apply MU. rewrite unsigned_lit by lia.
      unfold aimg_client in Hc. apply LbB_DPdK.outside_of.
      apply Forall_cons; [cbn [fst snd]; unfold ADS_STACK, AIMG_TOP in *; lia | apply Forall_nil]. }
    eapply stk_transport; [exact STK | exact MU | exact WM |]. intros x Hx. right.
    destruct (T3 x Hx) as [HV _]. pose proof (WM (wa x) HV) as HV'.
    assert (HX : AIMG_TOP <= bv_unsigned (wa x)) by (unfold wa; rewrite unsigned_lit by lia; unfold AIMG_TOP; lia).
    rewrite (BakeStackRep.wview_high m (wa x) HX) in HV'.
    destruct (m (wa x)) as [b|] eqn:Eb; [exists b; reflexivity | contradiction].
  Qed.

  Ltac evw0 := unfold estart, elenZ; cbn [edenot a_base a_off]; unfold HLib.Eseed, reg_ev, Wp0;
    lazy [ev eb N.ltb N.compare PosDef.Pos.compare PosDef.Pos.compare_cont N.to_nat PosDef.Pos.to_nat PosDef.Pos.iter_op
          Init.Nat.add Nat.sub nth app].

  Lemma kst_p1_ok : forall R X m, P1w m -> mem_inv asegs m -> know_ok asegs (HLib.Eseed R (Wp0 ++ X)) m kst_p1.
Proof.
    intros R X m HP MI. destruct (p1_keep m HP MI) as (AC & (RL & _) & ST).
    pose proof p1_ranges as (R1 & R2 & R3).
    pose proof (ACONST_shbase m AC) as [_ CS]. pose proof (ACONST_uar m AC) as [_ CU].
    clear HP. unfold ADS_STACK, AIMG_TOP, AAPP_HI in *.
    unfold know_ok, kst_p1. repeat apply Forall_cons; try apply Forall_nil.
    - apply kimg_relro. exact RL.
    - eapply (kword_of_rw_cells asegs _ m _ _ 0%nat _); [exact CS | reflexivity | reflexivity | lia
        | unfold estart; cbn [a_base a_off edenot]; rewrite unsigned_lit by lia; reflexivity
        | unfold ASHBASE_CELL; cbn; lia | unfold ASHBASE_CELL; cbn; lia | reflexivity].
    - eapply (kword_of_rw_cells asegs _ m _ _ 0%nat _); [exact CU | reflexivity | reflexivity | lia
        | unfold estart; cbn [a_base a_off edenot]; rewrite unsigned_lit by lia; reflexivity
        | unfold AUAR_CELL; cbn; lia | unfold AUAR_CELL; cbn; lia | reflexivity].
    - eapply kwr_of_stk; [exact ST | | |]; evw0; rewrite ?unsigned_lit by lia; lia.
    - cbn [kentry_ok]. evw0. lia.
  Qed.

  Definition tS0 (T : list fent) (ks : list (Z * nat)) : tab := (EVar 33, spz, -8192, 0, T, ks).

  Lemma tabs_wf1 : forall T ks, fwcl (wbound Wp0) T = true -> fin (-8192) 0 (fkeys T ++ ks) = true -> tabs_wf Wp0 [tS0 T ks].
Proof.
    intros T ks C1 F1. pose proof p1_ranges as (R1 & R2 & R3).
    assert (T1 : bv_unsigned (edenot (wenv Wp0) (EVar 33)) = spz) by reflexivity.
    split.
    - repeat constructor; cbn [tb tB tlo thi ttbl tks tS0]; try reflexivity; try assumption; unfold SHBASE, ADS_STACK in *; lia.
    - intros u1 u2 H1 H2 Hb. destruct H1 as [<-|[]]; destruct H2 as [<-|[]]. vm_compute in Hb. discriminate Hb.
  Qed.

  Lemma P1w_step : forall T ks m m', P1w m -> munch (winsT [tS0 T ks]) m m' -> wmono asegs m m' -> mem_inv asegs m' -> P1w m'.
Proof.
    intros T ks m m' [MU0 WM0] MU WM _. split; [| eapply wmono_trans; eassumption].
    eapply munch_trans; [exact MU0|]. eapply munch_weaken; [| exact MU]. apply sub_fp_of.
    unfold winsT. cbn [map tB tlo thi tS0]. apply Forall_cons; [| apply Forall_nil].
    exists (spz - 8192, spz). split; [left; reflexivity | cbn [fst snd]; lia].
  Qed.

  Lemma tabs_ok1 : forall m T ks, P1w m -> mem_inv asegs m -> ftbl Wp0 spz m T -> fin (-8192) 0 ks = true ->
    tabs_ok Wp0 m [tS0 T ks].
Proof.
    intros m T ks HP MI H1 F1. destruct (p1_keep m HP MI) as (_ & _ & ST).
    assert (WK : forall k w, In (k, w) ks -> wr_at asegs m (spz + k) (Z.of_nat w)).
    { intros k w Hi. destruct (fin_In _ _ _ k w F1 Hi) as (G1 & G2 & G3).
      pose proof LO as LO'. unfold ADS_STACK in LO'.
      pose proof (wr_at_of_stk asegs m lo spz ST) as W. eapply wr_at_sub; [exact W | lia | lia | lia]. }
    apply Forall_cons; [split; [exact H1 | exact WK] | apply Forall_nil].
  Qed.

  Ltac dkrun1 HRT HSF HP HMI fuel stops :=
    lazymatch goal with
    | |- evt asegs ?Q (MS ?R ?F (Z_to_bv 64 ?pc) ?fc None ?m ?ro) =>
      lazymatch type of HSF with ftbl _ _ _ ?SF =>
      lazymatch type of HRT with rtbl _ _ ?RT =>
        let L0 := constr:([tS0 SF []]) in
        let r := eval vm_compute in
          (sym_exec asegs fuel true stops (SCR [] [] []) (SS pc (HLib.srs sr_id RT) [] (kst_p1 ++ fknT L0) 60) []) in
        lazymatch r with
        | (?SSr, ?scs, ?scr') =>
          let RT' := eval vm_compute in (wtbl (wbound Wp0) (s_regs SSr)) in
          let ks1 := eval vm_compute in (nkeys (EVar 33) (s_log SSr) SF) in
          eapply (dk_runN Wp0 [tS0 SF ks1] (tabs_wf1 SF ks1 ltac:(vm_compute; reflexivity) ltac:(vm_compute; reflexivity))
                    P1w (P1w_step SF ks1) Q R F pc fc m ro RT [] kst_p1 fuel stops (SCR [] [] []) 60%N SSr scs scr' RT');
          [ assumption | exact HRT | vm_compute; reflexivity
          | apply tabs_ok1; [exact HP | exact HMI | exact HSF | vm_compute; reflexivity]
          | exact HP | exact HMI | apply kst_p1_ok; [exact HP | exact HMI]
          | vm_cast_no_check (@eq_refl _ (SSr, scs, scr'))
          | | vm_compute; reflexivity | vm_compute; reflexivity | ]
        end
      end end
    end.

  Lemma HHb : asan_rt_hyps H.
  Proof. exact (rt_bp_base H HHbp). Qed.
  Lemma SM2 : stack_malloc_stmt_bp H 2 AFS_MALLOC_2.
  Proof. exact (proj1 (proj2 (rt_bp_ext H HHbp))). Qed.

  Definition W1 (ff fp : Z) : list (Z * Z) :=
    [(spz - 8192, spz); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 256); (sh ff, sh ff + 32)].

  Lemma new_frame : forall m ff fp, as_RFS H ((2, ff, fp) :: LF) m ->
    fresh_frame H LF 2 ff fp
    /\ (ff + 256 <= ds \/ ds + DS_SIZE <= ff) /\ (ff + 256 <= pcons \/ pcons + 48 <= ff)
    /\ (fp + 1 <= pcons \/ pcons + 48 <= fp) /\ (fp + 1 <= ds \/ ds + DS_SIZE <= fp)
    /\ (hull_hi (ds + DS_SIZE) <= ff \/ ff + 256 <= hull_lo ds)
    /\ ds + DS_SIZE <= aceil /\ ds + DS_SIZE + 64 <= AAPP_HI.
  Proof.
    intros m ff fp RF.
    pose proof (fresh_of_RFS H HHb LF 2 ff fp m RF) as FRESH.
    destruct (ah_RFS_range H HHb _ _ RF) as [FO FR].
    pose proof FO as (B1 & B2 & B3 & B4).
    pose proof (FR (2, ff, fp) (or_introl eq_refl)) as (K1 & K2 & K3 & (K4 & K5) & K6).
    cbn [ff_class ff_addr ff_flag fst snd] in K1, K2, K3, K4, K5, K6. unfold fsz in K3. change (64 * 2 ^ 2) with 256 in K3.
    pose proof aceil_facts as ((A1 & A2) & A3 & A4).
    assert (FRM : forall f, In f LF -> (ff + 256 <= ff_addr f \/ ff_addr f + fsz (ff_class f) <= ff)
      /\ as_FSB H + AFS_HDR <= ff_addr f /\ ff_addr f + fsz (ff_class f) <= as_FSB H + AFS_SIZE
      /\ ff_addr f mod 64 = 0 /\ fsz (ff_class f) mod 64 = 0).
    { intros f Hf. destruct FRESH as (_ & _ & D). destruct (D f Hf) as [D1 _].
      unfold fsz in D1 at 1. change (64 * 2 ^ 2) with 256 in D1.
      pose proof (FR f (or_intror Hf)) as (L1 & L2 & L3 & (L4 & L5) & L6).
      split; [exact D1|]. split; [exact L2|]. split; [exact L3|]. split; [exact L4|].
      unfold fsz. rewrite Z.mul_comm. apply Z_mod_mult. }
    assert (FSO : forall O n, fsobj H LF O n -> (ff + 256 <= O \/ O + n <= ff) /\ (fp + 1 <= O \/ O + n <= fp)).
    { intros O n [OB | (f & Hf & F1 & F2)].
      - clear - OB K2 K3 K6. unfold AFS_HDR, AFS_FLAGS, AFS_SIZE in *. lia.
      - destruct (FRM f Hf) as (D1 & L2 & L3 & _). clear - D1 L2 F1 F2 K6. unfold AFS_HDR, AFS_FLAGS in *. lia. }
    destruct (FSO pcons 48 PCfs) as [PC1 PC2].
    pose proof DSin as (f & Hf & F1 & F2).
    destruct (FRM f Hf) as (D1 & L2 & L3 & L4 & FM).
    split; [exact FRESH|].
    split; [clear - D1 F1 F2; lia|].
    split; [clear - PC1; lia|].
    split; [clear - PC2; lia|].
    split; [clear - K6 L2 F1 F2; unfold AFS_HDR, AFS_FLAGS in *; lia|].
    split; [unfold hull_lo, hull_hi; clear - D1 F1 F2 L4 FM K4; Z.div_mod_to_equations; lia|].
    split; [clear - F2 L3 B2; lia|].
    clear - F2 L3 B2 A1 A2. unfold AAPP_HI. lia.
  Qed.

  Lemma W1_keep : forall m ff fp, munch (W1 ff fp) m0 m -> wmono asegs m0 m -> fresh_frame H LF 2 ff fp ->
    (ff + 256 <= ds \/ ds + DS_SIZE <= ff) -> (ff + 256 <= pcons \/ pcons + 48 <= ff) ->
    (fp + 1 <= pcons \/ pcons + 48 <= fp) -> (fp + 1 <= ds \/ ds + DS_SIZE <= fp) ->
    (hull_hi (ds + DS_SIZE) <= ff \/ ff + 256 <= hull_lo ds) -> ds + DS_SIZE <= aceil ->
    addressable m ds DS_SIZE /\ wr_at asegs m ds DS_SIZE /\ shvis m ds (ds + DS_SIZE)
    /\ addressable m pcons 48 /\ rw_cells asegs m (pcons + 32) [C8 (Z_to_bv 64 0)] /\ LINV_P5 m /\ stk asegs m lo spz
    /\ addressable m (p + 8) 8 /\ addressable m (p + 80) 8
    /\ ro_cells asegs m (p + 8) [C8 (Z_to_bv 64 pcons)] /\ ro_cells asegs m (p + 80) [C8 (Z_to_bv 64 icount)]
    /\ app_obj (p + 8) 8 /\ app_obj (p + 80) 8 /\ p mod 8 = 0 /\ pcons mod 16 = 0
    /\ (forall O, O = p + 8 \/ O = p + 80 -> O + 8 <= spz - ADS_STACK \/ spz <= O)
    /\ (forall O, O = p + 8 \/ O = p + 80 -> ff + 256 <= O \/ O + 8 <= ff)
    /\ (forall O, O = p + 8 \/ O = p + 80 -> fp + 1 <= O \/ O + 8 <= fp)
    /\ (forall O, O = p + 8 \/ O = p + 80 -> sh ff + 32 <= O \/ O + 8 <= sh ff).
  Proof.
    intros m ff fp MU WM (FFR & FO & FRD) FFDS FFPC FPPC FPDS HULL DAC.
    pose proof FO as (B1 & B2 & B3 & B4).
    pose proof FFR as (K1 & K2 & K3 & (K4 & K5) & K6). unfold fsz in K3. change (64 * 2 ^ 2) with 256 in K3.
    pose proof aceil_facts as ((A1 & A2) & A3 & A4).
    pose proof (bv_unsigned_in_range 64 sp) as R. change (bv_modulus 64) with (2 ^ 64) in R.
    assert (B4' : as_FSB H + AFS_SIZE <= ALOWSH_LO \/ AHI_LO <= as_FSB H).
    { clear - B4. unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO, AIMG_TOP in *. destruct B4; [left | right]; lia. }
    pose proof DSO as (O1 & O2 & O3). pose proof PCO as (Q1 & Q2 & Q3).
    pose proof PPO as (PA8 & P8M & PF8 & _ & _ & PS8 & PO8).
    pose proof PIO as (PA80 & P80M & PF80 & _ & _ & PS80 & PO80).
    assert (SHA : forall A n, AIMG_TOP <= A -> A mod 8 = 0 -> 0 <= n -> A + n <= AAPP_HI -> (A + n <= ff \/ ff + 256 <= A) ->
      disjoint_from (W1 ff fp) (sh A) (nsh n)).
    { intros A n H1 H2 H3 H5 H6.
      assert (N8 : (nsh n = n / 8 /\ n = n / 8 * 8) \/ (nsh n = n / 8 + 1 /\ n / 8 * 8 < n < n / 8 * 8 + 8))
        by (clear - H3; unfold nsh; Z.div_mod_to_equations; lia).
      assert (EA : A = A / 8 * 8) by (clear - H2; Z.div_mod_to_equations; lia).
      assert (EN : 0 <= n / 8) by (clear - H3; Z.div_mod_to_equations; lia).
      assert (EF : ff = ff / 8 * 8) by (clear - K4; Z.div_mod_to_equations; lia).
      unfold W1. cbn [disjoint_from]. unfold sh.
      clear - H1 H2 H3 H5 H6 EA EN EF N8 K2 K3 K6 B1 B2 B4' A1 A2 CEIL LO.
      unfold ADS_STACK, AFS_HDR, AFS_SIZE, AFS_FLAGS, AIMG_TOP, ALOWSH_LO, AHI_LO, AAPP_HI, ASHADOW_BASE in *.
      set (a8 := A / 8) in *. set (n8 := n / 8) in *. set (f8 := ff / 8) in *. set (ns := nsh n) in *. lia. }
    assert (SHO : forall O n, app_obj O n -> sh ff + 32 <= O \/ O + n <= sh ff).
    { intros O n (Z1 & Z2 & Z3).
      assert (E : ff / 8 * 8 <= ff < ff / 8 * 8 + 8) by (clear; Z.div_mod_to_equations; lia).
      clear - Z1 Z2 Z3 E K2 K3 B1 B2 A2.
      unfold sh, ASHADOW_BASE, AIMG_TOP, ALOWSH_LO, AHI_LO, AAPP_HI, AFS_HDR, AFS_SIZE in *. set (f8 := ff / 8) in *. lia. }
    assert (FSO : forall O n, fsobj H LF O n -> (ff + 256 <= O \/ O + n <= ff) /\ (fp + 1 <= O \/ O + n <= fp)
      /\ (O + n <= as_FSB H \/ as_FSB H + AFS_HDR <= O)).
    { destruct (ah_RFS_range H HHb _ _ RFS0) as [_ FR0].
      intros O n [OB | (f & Hf & F1 & F2)].
      - clear - OB K2 K3 K6. unfold AFS_HDR, AFS_FLAGS, AFS_SIZE in *. lia.
      - destruct (FRD f Hf) as [D1 _]. unfold fsz in D1 at 1. change (64 * 2 ^ 2) with 256 in D1.
        pose proof (FR0 f Hf) as (L1 & L2 & _).
        clear - D1 L2 F1 F2 K6. unfold AFS_HDR, AFS_FLAGS in *. lia. }
    pose proof (FSO pcons 48 PCfs) as (_ & _ & PCF).
    pose proof (SPOBJ pcons 48 ltac:(clear; tauto)) as SC.
    assert (PPS : forall O, O = p + 8 \/ O = p + 80 -> O + 8 <= spz - ADS_STACK \/ spz <= O).
    { intros O [-> | ->]; [exact PS8 | exact PS80]. }
    assert (PPF : forall O, O = p + 8 \/ O = p + 80 -> ff + 256 <= O \/ O + 8 <= ff).
    { intros O [-> | ->]; [exact (proj1 (FSO _ _ PF8)) | exact (proj1 (FSO _ _ PF80))]. }
    assert (PPL : forall O, O = p + 8 \/ O = p + 80 -> fp + 1 <= O \/ O + 8 <= fp).
    { intros O [-> | ->]; [exact (proj1 (proj2 (FSO _ _ PF8))) | exact (proj1 (proj2 (FSO _ _ PF80)))]. }
    assert (PPH : forall O, O = p + 8 \/ O = p + 80 -> sh ff + 32 <= O \/ O + 8 <= sh ff).
    { intros O [-> | ->]; [exact (SHO _ _ PO8) | exact (SHO _ _ PO80)]. }
    assert (PPW : forall O, O = p + 8 \/ O = p + 80 -> disjoint_from (W1 ff fp) O 8).
    { intros O HO.
      pose proof (PPS O HO) as E1. pose proof (PPF O HO) as E2. pose proof (PPL O HO) as E3. pose proof (PPH O HO) as E4.
      assert (E5 : O + 8 <= as_FSB H \/ as_FSB H + AFS_HDR <= O)
        by (destruct HO as [-> | ->]; [exact (proj2 (proj2 (FSO _ _ PF8))) | exact (proj2 (proj2 (FSO _ _ PF80)))]).
      unfold W1. cbn [disjoint_from]. clear - E1 E2 E3 E4 E5.
      unfold ADS_STACK, AFS_FLAGS, AFS_HDR in *. repeat split; lia. }
    split.
    { eapply addressable_transport; [exact DSA | exact MU | exact WM |].
      apply SHA; [exact O1 | exact DS8 | clear; unfold DS_SIZE; lia | exact O3 | clear - FFDS; lia]. }
    split; [eapply wr_at_transport; [exact DSW | exact WM]|].
    split.
    { eapply shvis_transport; [exact DSV | exact MU | exact WM |].
      unfold W1, hull_lo, hull_hi in *. cbn [disjoint_from].
      clear - O1 O2 O3 HULL DAC K2 K3 K4 K6 B1 B2 B4' A1 A2 CEIL LO.
      unfold sh, DS_SIZE, ADS_STACK, AFS_HDR, AFS_SIZE, AFS_FLAGS, AIMG_TOP, ALOWSH_LO, AHI_LO, AAPP_HI, ASHADOW_BASE in *.
      Z.div_mod_to_equations. lia. }
    split.
    { eapply addressable_transport; [exact PCA | exact MU | exact WM |].
      apply SHA; [exact Q1 | exact PC8 | clear; lia | exact Q3 | clear - FFPC; lia]. }
    split.
    { eapply rw_cells_transport; [exact PCC | exact MU | exact WM |]. cbn [cells_size csize Nat.add Z.of_nat].
      pose proof (SHO pcons 48 PCO) as SHF.
      unfold W1. cbn [disjoint_from]. clear - SC PCF SHF FFPC FPPC.
      unfold ADS_STACK, AFS_FLAGS, AFS_HDR in *. lia. }
    split.
    { eapply LINV_P5_cl; [exact LV0|]. intros a Ha Hc. unfold wa. apply MU. rewrite unsigned_lit by lia.
      assert (AT : a < AIMG_TOP) by (clear - Hc; unfold aimg_client, AIMG_TOP in *; lia).
      assert (F8 : 0 <= ff / 8) by (apply Z.div_pos; unfold AFS_HDR, AIMG_TOP in *; lia).
      apply LbB_DPdK.outside_of. unfold W1. unfold sh.
      clear - AT F8 B1 K6 K2 CEIL LO A1. unfold ADS_STACK, AFS_HDR, AFS_FLAGS, AIMG_TOP, ASHADOW_BASE in *.
      repeat (apply Forall_cons; [cbn [fst snd]; lia|]). apply Forall_nil. }
    split.
    { eapply stk_transport; [exact STK | exact MU | exact WM |]. intros x Hx. right.
      pose proof STK as (S1 & S2 & S3). destruct (S3 x Hx) as [HV _].
      pose proof (WM (wa x) HV) as HV'.
      assert (HX : AIMG_TOP <= bv_unsigned (wa x)) by (unfold wa; rewrite unsigned_lit by lia; unfold AIMG_TOP; lia).
      rewrite (BakeStackRep.wview_high m (wa x) HX) in HV'.
      destruct (m (wa x)) as [b|] eqn:Eb; [exists b; reflexivity | contradiction]. }
    split.
    { eapply addressable_transport; [exact PA8 | exact MU | exact WM |].
      pose proof PO8 as (Z1 & _ & Z3). pose proof (PPF (p + 8) (or_introl eq_refl)) as E.
      apply SHA; [exact Z1 | exact P8M | clear; lia | exact Z3 | clear - E; lia]. }
    split.
    { eapply addressable_transport; [exact PA80 | exact MU | exact WM |].
      pose proof PO80 as (Z1 & _ & Z3). pose proof (PPF (p + 80) (or_intror eq_refl)) as E.
      apply SHA; [exact Z1 | exact P80M | clear; lia | exact Z3 | clear - E; lia]. }
    split; [eapply ro_cells_transport; [exact PPC | exact MU | exact (PPW (p + 8) (or_introl eq_refl))]|].
    split; [eapply ro_cells_transport; [exact PIC | exact MU | exact (PPW (p + 80) (or_intror eq_refl))]|].
    split; [exact PO8|]. split; [exact PO80|].
    split; [clear - P8M; Z.div_mod_to_equations; lia|].
    split; [exact PC16|].
    split; [exact PPS|]. split; [exact PPF|]. split; [exact PPL|]. exact PPH.
  Qed.

  Lemma athr_keep : forall m m' x y, athr_cells m -> munch [(x, y)] m m' -> wmono asegs m m' -> aceil <= x -> athr_cells m'.
  Proof.
    intros m m' x y (ctx & T & D & tb & te & C1 & C2 & C3 & C4 & C5 & B1 & B2 & B3 & B4 & B5 & B6 & B7 & B8 & B9) MU WM HX.
    pose proof aceil_facts as ((A1 & A2) & A3 & A4).
    assert (DJ : forall A n, A + n <= aceil -> disjoint_from [(x, y)] A n).
    { intros A n HA. cbn [disjoint_from]. split; [left; lia | exact I]. }
    exists ctx, T, D, tb, te.
    split; [eapply rw_cells_transport; [exact C1 | exact MU | exact WM | apply DJ; cbn [cells_size csize Nat.add Z.of_nat];
                                        clear - A1; unfold ATSD0 in *; lia]|].
    split; [eapply rw_cells_transport; [exact C2 | exact MU | exact WM | apply DJ; cbn [cells_size csize Nat.add Z.of_nat];
                                        clear - B3; lia]|].
    split; [eapply rw_cells_transport; [exact C3 | exact MU | exact WM | apply DJ; cbn [cells_size csize Nat.add Z.of_nat];
                                        clear - B6; lia]|].
    split; [eapply rw_cells_transport; [exact C4 | exact MU | exact WM | apply DJ; cbn [cells_size csize Nat.add Z.of_nat];
                                        clear - A1; unfold ATP in *; lia]|].
    split; [eapply rw_cells_transport; [exact C5 | exact MU | exact WM | apply DJ; cbn [cells_size csize Nat.add Z.of_nat];
                                        clear - B9; lia]|].
    repeat match goal with |- _ /\ _ => split end; assumption.
  Qed.

  Definition pdF : machine_state -> Prop :=
    fun ms => exists ff fp m1, fresh_frame H LF 2 ff fp /\ munch (W1 ff fp) m0 m1 /\ wmono asegs m0 m1
              /\ LbB_DPdK.pd_P H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m1 ds err ff fp LF ms.

#[local] Definition HTLbADPd_0 : list (reg * expr) := [(1%bv, EVar 34); (2%bv, EVar 33); (3%bv, EVar 50); (4%bv, EVar 51); (8%bv, EVar 38); (9%bv, EVar 39); (18%bv, EVar 40); (19%bv, EVar 41); (20%bv, EVar 42); (21%bv, EVar 43); (22%bv, EVar 44); (23%bv, EVar 45); (24%bv, EVar 46); (25%bv, EVar 47); (26%bv, EVar 48); (27%bv, EVar 49); (10%bv, EVar 32); (11%bv, EVar 35); (12%bv, EVar 36); (13%bv, EVar 37)].
#[local] Definition HTLbADPd_1 : list (reg * expr) := [(2%bv, EAlu ALU_ADD (EVar 33) (ELit (-128))); (9%bv, EAlu ALU_ADD (EVar 33) (ELit (-128))); (10%bv, EVar 52)].
#[local] Definition HTLbADPd_2 : list (reg * expr) := [(2%bv, EAlu ALU_ADD (EVar 33) (ELit (-144))); (9%bv, EAlu ALU_ADD (EVar 33) (ELit (-144))); (10%bv, EVar 52)].
  Ltac pd_rt2 R1 HRT1 KP ER2 K2e K9 EAd Ha2 :=
    repeat apply Forall_cons; try apply Forall_nil; cbn [fst snd];
    lazymatch goal with
    | |- PropExec.getr _ ?r = _ =>
      first
        [ rewrite (KP r ltac:(inkept));
          first
            [ rewrite K2e; cbv beta delta [LbB_DPd0A.spx LbB_DPd0B.spx];
              rewrite EAd by first [reflexivity | assumption | (clear; lia)]; f_equal; clear; lia
            | rewrite K9, K2e; cbv beta delta [LbB_DPd0A.spx LbB_DPd0B.spx];
              rewrite EAd by first [reflexivity | assumption | (clear; lia)]; f_equal; clear; lia
            | lazymatch type of HRT1 with rtbl _ _ ?T1 =>
                let e := eval vm_compute in (List.find (fun pr => Z.eqb (bv_unsigned (fst pr)) (bv_unsigned r)) T1) in
                lazymatch e with Some (_, ?e0) =>
                  rewrite (rtbl_In Wp0 R1 _ r e0 HRT1 ltac:(apply LbB_DCtorK.inb_In'; vm_compute; reflexivity))
                end
              end;
              first [reflexivity | (rewrite Ha2; reflexivity)] ]
        | rewrite ER2; reflexivity ]
    end.

  Lemma pd_walk :
    evt asegs pdF (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 aw a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                      F (Z_to_bv 64 APDIAG) fc None m0 (seg_rom asegs)).
  Proof using All.
    pose proof p1_ranges as (R1' & R2' & R3').
    assert (RF0 : rfull (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 aw a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6))
      by apply rfull_mkR.
    assert (HRT : rtbl Wp0 (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 aw a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                  HTLbADPd_0).
    { unfold rtbl, HTLbADPd_0. repeat constructor; cbn [fst snd]; first [exact Ha0 | exact Ha1 | exact Ha2]. }
    assert (HSF : ftbl Wp0 spz m0 []) by apply ftbl_nil.
    assert (HP : P1w m0) by (split; [apply munch_refl | apply wmono_refl]).
    try unfold APDIAG.
    dkrun1 HRT HSF HP MI0 600%nat [AFS_MALLOC_2].
    { constructor. }
    intros R1 m1 RF1 HRT1 HTS1 HP1 HMI1 MU1 WM1.
    lazymatch type of HTS1 with ftbls _ _ ?T =>
      let l := eval vm_compute in T in
      let E := fresh "E" in assert (E : T = l) by (vm_compute; reflexivity); rewrite E in HTS1; clear E end.
    apply Forall_cons_iff in HTS1 as [HSF1 _]. cbn [fst snd] in HSF1.
    cbn [s_pc].
    destruct (p1_keep m1 HP1 HMI1) as (AC1 & LV1 & ST1).
    assert (K1 : PropExec.getr R1 1 = Z_to_bv 64 LbB_DPd0A.RET_MALLOC).
    { apply (rtbl_In Wp0 R1 _ 1%bv (ELit LbB_DPd0A.RET_MALLOC) HRT1). apply LbB_DCtorK.inb_In'. vm_compute. reflexivity. }
    assert (K4 : PropExec.getr R1 4 = tp).
    { apply (rtbl_In Wp0 R1 _ 4%bv (EVar 51) HRT1). apply LbB_DCtorK.inb_In'. vm_compute. reflexivity. }
    assert (K2e : PropExec.getr R1 2 = Z_to_bv 64 ((spz - 96) - (spz - 96) mod 32)).
    { rewrite (rtbl_In Wp0 R1 _ 2%bv (EMd M_MUL (ELit 32) (EAlu ALU_SRL (EAlu ALU_ADD (EVar 33) (ELit (-96))) (ELit 5))) HRT1
                ltac:(apply LbB_DCtorK.inb_In'; vm_compute; reflexivity)). cbn [edenot].
      change (ev (wenv Wp0) 33) with sp.
      assert (EA : alu64 ALU_ADD sp (Z_to_bv 64 (-96)) = Z_to_bv 64 (spz - 96)).
      { rewrite <- (Z_to_bv_bv_unsigned sp) at 1. rewrite w_addm by (clear - R1' R2' R3'; unfold ADS_STACK in *; lia).
        f_equal; clear; lia. }
      rewrite EA. rewrite pd_mul32 by (clear - R1' R2' R3'; unfold ADS_STACK in *; lia). reflexivity. }
    assert (K9 : PropExec.getr R1 9 = PropExec.getr R1 2).
    { rewrite (rtbl_In Wp0 R1 _ 9%bv (EMd M_MUL (ELit 32) (EAlu ALU_SRL (EAlu ALU_ADD (EVar 33) (ELit (-96))) (ELit 5))) HRT1
                ltac:(apply LbB_DCtorK.inb_In'; vm_compute; reflexivity)).
      rewrite (rtbl_In Wp0 R1 _ 2%bv (EMd M_MUL (ELit 32) (EAlu ALU_SRL (EAlu ALU_ADD (EVar 33) (ELit (-96))) (ELit 5))) HRT1
                ltac:(apply LbB_DCtorK.inb_In'; vm_compute; reflexivity)).
      reflexivity. }
    assert (SPA0 : exists spa, spa = (spz - 96) - (spz - 96) mod 32) by (eexists; reflexivity).
    destruct SPA0 as [spa Espa]. rewrite <- Espa in K2e.
    assert (SPC : spa = spz - 96 \/ spa = spz - 112).
    { subst spa. clear - SP16. Z.div_mod_to_equations. lia. }
    clear Espa.
    assert (Us : bv_unsigned (PropExec.getr R1 2) = spa)
      by (rewrite K2e; apply unsigned_lit; clear - SPC R1' R2' R3'; unfold ADS_STACK in *; lia).
    unfold winsT in MU1. cbn [map tB tlo thi tS0] in MU1.
    assert (RFS1 : as_RFS H LF m1).
    { destruct (ah_RFS_range H HHb LF m0 RFS0) as [(B1 & B2 & B3 & B4) _].
      eapply (ah_RFS_frame H HHb); [exact RFS0 | exact MU1 | exact WM1 |].
      apply Forall_cons; [| apply Forall_nil]. left. cbn [fst snd].
      clear - R1' R2' R3' B2. unfold ATLS_PRIV_LO, ATLS_PRIV_HI, ATP, ADS_STACK, AFS_SIZE in *. lia. }
    assert (THR1 : athr_cells m1).
    { eapply (athr_keep m0 m1 (spz + -8192) (spz + 0)); [exact THR | exact MU1 | exact WM1 | clear - R2'; unfold ADS_STACK in *; lia]. }
    pose proof LO as LO'. unfold ADS_STACK in LO'.
    rewrite (MS_full_eq R1 F _ fc m1 _ RF1).
    eapply evt_cut.
    { apply (SM2 (PropExec.getr R1 1) (PropExec.getr R1 2) (PropExec.getr R1 3) (PropExec.getr R1 4) (PropExec.getr R1 5)
               (PropExec.getr R1 6) (PropExec.getr R1 7) (PropExec.getr R1 8) (PropExec.getr R1 9) (PropExec.getr R1 10)
               (PropExec.getr R1 11) (PropExec.getr R1 12) (PropExec.getr R1 13) (PropExec.getr R1 14) (PropExec.getr R1 15)
               (PropExec.getr R1 16) (PropExec.getr R1 17) (PropExec.getr R1 18) (PropExec.getr R1 19) (PropExec.getr R1 20)
               (PropExec.getr R1 21) (PropExec.getr R1 22) (PropExec.getr R1 23) (PropExec.getr R1 24) (PropExec.getr R1 25)
               (PropExec.getr R1 26) (PropExec.getr R1 27) (PropExec.getr R1 28) (PropExec.getr R1 29) (PropExec.getr R1 30)
               (PropExec.getr R1 31) F fc m1 LF lo RFS1 LFn).
      all: first [ (rewrite Us; destruct (stk_split asegs m1 lo spa spz ST1 ltac:(clear - LO' SPC; lia)) as [S _]; exact S)
                 | exact CEIL
                 | (rewrite Us; clear - LO' SPC; unfold AFS_STACK in *; lia)
                 | exact HMI1 | (rewrite K4; exact TP) | exact AC1 | exact THR1 ]. }
    intros ms2 (t0' & t1' & t2' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m2 & ff & fp & junk1 & junk2
                & E2 & MU2 & WM2 & MI2 & ST2 & RF2 & FRC & SHF & FLG & AC2).
    subst ms2. rewrite K1, ret_pc_even; [| clear; unfold LbB_DPd0A.RET_MALLOC; lia | reflexivity].
    replace (fsz 2) with 256 in MU2 by reflexivity. replace (fshn 2) with 32 in MU2 by reflexivity.
    try rewrite Us in MU2, ST2.
    lazymatch goal with |- evt _ _ (MS ?RR _ _ _ _ _ _) => remember RR as R2 eqn:ER2 end.
    assert (RF2' : rfull R2) by (rewrite ER2; apply rfull_mkR).
    assert (KP : forall r, In r KEPT -> PropExec.getr R2 r = PropExec.getr R1 r).
    { intros r Hr. rewrite ER2. apply (getr_mkR_keptR R1); [exact (eq_sym K1) | exact Hr]. }
    destruct (new_frame m2 ff fp RF2) as (FRESH & FFDS & FFPC & FPPC & FPDS & HULL & DSM & DSH).
    assert (MUW : munch (W1 ff fp) m0 m2).
    { eapply munch_trans; [eapply munch_weaken; [| exact MU1] | eapply munch_weaken; [| exact MU2]]; apply sub_fp_of.
      - apply Forall_cons; [| apply Forall_nil]. exists (spz - 8192, spz). split; [left; reflexivity | cbn; clear; lia].
      - unfold W1.
        apply Forall_cons;
          [exists (spz - 8192, spz); split; [left; reflexivity | cbn; clear - SPC; unfold AFS_STACK in *; lia]|].
        apply Forall_cons; [exists (as_FSB H, as_FSB H + AFS_FLAGS); split; [right; left; reflexivity | cbn; clear; lia]|].
        apply Forall_cons; [exists (fp, fp + 1); split; [right; right; left; reflexivity | cbn; clear; lia]|].
        apply Forall_cons;
          [exists (ff, ff + 256); split; [right; right; right; left; reflexivity | cbn; try unfold fsz; cbn; clear; lia]|].
        apply Forall_cons;
          [exists (sh ff, sh ff + 32); split; [right; right; right; right; left; reflexivity | cbn; try unfold fshn; cbn; clear; lia]|].
        apply Forall_nil. }
    assert (WMW : wmono asegs m0 m2) by (eapply wmono_trans; [exact WM1 | exact WM2]).
    destruct (W1_keep m2 ff fp MUW WMW FRESH FFDS FFPC FPPC FPDS HULL DSM)
      as (DSA2 & DSW2 & DSV2 & PCA2 & PCC2 & LV2 & ST2' & PPA8 & PPA80 & PPC8 & PPC80 & PPO8 & PPO80 & PP8 & P16
          & PPS & PPF & PPL & PPH).
    assert (FRW2 : wr_at asegs m2 ff 256) by (destruct FRC as [_ W]; exact W).
    assert (FSV2 : shvis m2 ff (ff + 256)) by exact (ah_frm_shvis H HHb _ m2 (2, ff, fp) RF2 (or_introl eq_refl)).
    assert (FSW2 : wr_at asegs m2 (sh ff) 32) by (destruct SHF as (_ & _ & _ & W); exact W).
    assert (FLW2 : wr_at asegs m2 fp 1) by (destruct FLG as [_ W]; exact W).
    pose proof FRESH as (FFR & FSB_OK & _).
    pose proof FFR as (K1' & K2' & K3' & (K4' & K5') & K6'). unfold fsz in K3'. try change (64 * 2 ^ 2) with 256 in K3'.
    pose proof FSB_OK as (B1 & B2 & B3 & B4).
    pose proof aceil_facts as ((A1 & A2) & _).
    assert (SHF0 : sh ff + 32 <= spz - 96).
    { clear - K3' B2 A1 R2' R3'. unfold sh, ASHADOW_BASE, AFS_SIZE, ADS_STACK in *. Z.div_mod_to_equations. lia. }
    assert (HSF2w : ftbl Wp0 spz m2 LbB_DPd0A.SF2).
    { eapply (ftbl_munch Wp0 spz m1 m2 _ _ (-96) 0);
        [ apply (ftbl_sub _ _ _ _ _ HSF1); vm_compute; reflexivity | exact MU2 | exact WM2 | vm_compute; reflexivity |].
      cbn [disjoint_from].
      clear - SPC K2' K3' K6' B2 SHF0 R1' R2' R3' LO CEIL.
      unfold AFS_STACK, ADS_STACK, AFS_SIZE, AFS_HDR, AFS_FLAGS in *. lia. }
    assert (HSF2 : ftbl (LbB_DPdK.Wp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 ds pcons icount ff fp p) spz m2
                        LbB_DPd0A.SF2).
    { unfold ftbl, LbB_DPd0A.SF2 in HSF2w |- *.
      let rec go X :=
        lazymatch type of X with
        | Forall _ (_ :: _) =>
            let A := fresh "A" in let Y := fresh "Y" in
            apply Forall_cons_iff in X as [A Y]; apply Forall_cons; [exact A | go Y]
        | _ => apply Forall_nil
        end in go HSF2w. }
    assert (HFT2 : ftbl (LbB_DPdK.Wp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 ds pcons icount ff fp p) ff m2
                        LbB_DPd0A.FT2).
    { apply (ftbl_of_C8 _ ff m2 248 (EVar 53)).
      pose proof FRC as FRC'.
      apply (proj1 (rw_cells_app asegs m2 ff [CB 24 junk1; C8 (PropExec.getr R1 2); CB (Z.to_nat (fsz 2 - 40)) junk2]
                                 [C8 (Z_to_bv 64 fp)])) in FRC'.
      destruct FRC' as [_ FRC2]. exact FRC2. }
    assert (HHT2 : ftbl (LbB_DPdK.Wp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 ds pcons icount ff fp p) (ff / 8) m2 [])
      by apply ftbl_nil.
    assert (EAd : forall W d, ev (wenv W) 33 = sp -> 0 <= spz + d < 2 ^ 64 -> - 2 ^ 63 < d < 0 ->
              edenot (wenv W) (EAlu ALU_ADD (EVar 33) (ELit d)) = Z_to_bv 64 (spz + d)).
    { intros W d E Hd1 Hd2. cbn [edenot]. rewrite E.
      rewrite <- (Z_to_bv_bv_unsigned sp) at 1. apply w_addm; clear - Hd1 Hd2 R1'; lia. }
    assert (SP96 : 0 <= spz + -96 < 2 ^ 64) by (clear - R1' R2' R3'; unfold ADS_STACK in *; lia).
    assert (SP112 : 0 <= spz + -112 < 2 ^ 64) by (clear - R1' R2' R3'; unfold ADS_STACK in *; lia).
    assert (PD : evt asegs (LbB_DPdK.pd_P H ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc m2 ds err ff fp LF)
                   (MS R2 F (Z_to_bv 64 LbB_DPd0A.RET_MALLOC) fc None m2 (seg_rom asegs))).
    { destruct SPC as [SA | SB].
      - rewrite SA in K2e.
        assert (HRT2 : rtbl (LbB_DPdK.Wp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 ds pcons icount ff fp p) R2
                            LbB_DPd0A.RT2).
        { unfold rtbl, LbB_DPd0A.RT2. pd_rt2 R1 HRT1 KP ER2 K2e K9 EAd Ha2. }
        eapply (@LbB_DPd0A.pd2 HCEIL H HHbp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 F fc m2 ds pcons icount err lo
                  ff fp p LF).
        all: eassumption.
      - rewrite SB in K2e.
        assert (HRT2 : rtbl (LbB_DPdK.Wp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 ds pcons icount ff fp p) R2
                            LbB_DPd0B.RT2).
        { unfold rtbl, LbB_DPd0B.RT2. pd_rt2 R1 HRT1 KP ER2 K2e K9 EAd Ha2. }
        assert (HSF2B : ftbl (LbB_DPdK.Wp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 ds pcons icount ff fp p) spz m2
                             LbB_DPd0B.SF2) by exact HSF2.
        assert (HFT2B : ftbl (LbB_DPdK.Wp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 ds pcons icount ff fp p) ff m2
                             LbB_DPd0B.FT2) by exact HFT2.
        eapply (@LbB_DPd0B.pd2 HCEIL H HHbp ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 a2 F fc m2 ds pcons icount err lo
                  ff fp p LF).
        all: eassumption. }
    eapply evt_mono; [exact PD |].
    intros ms' PP. unfold pdF. exists ff, fp, m2.
    split; [exact FRESH |]. split; [exact MUW |]. split; [exact WMW | exact PP].
  Qed.

  Lemma pd0_full : err = -4 ->
    evt asegs pdF (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 aw a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                      F (Z_to_bv 64 APDIAG) fc None m0 (seg_rom asegs)).
  Proof using All. intros _. exact pd_walk. Qed.
  Lemma pdE_full :
    evt asegs pdF (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 aw a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                      F (Z_to_bv 64 APDIAG_E) fc None m0 (seg_rom asegs)).
  Proof using All. exact pd_walk. Qed.

  Definition TW (ff fp : Z) : list (Z * Z) :=
    [(spz - 16384, spz); (as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + 256); (sh ff, sh ff + 32);
     (ds, ds + DS_SIZE)].

  Lemma tw_munch : forall ff fp m1 m', munch (W1 ff fp) m0 m1 -> munch (LbB_DPdK.PW sp ds ff fp) m1 m' ->
    munch (TW ff fp) m0 m'.
  Proof.
    intros ff fp m1 m' M1 M2 x Hx. unfold TW in Hx. cbn [outside] in Hx.
    transitivity (m1 x).
    - apply M2. unfold LbB_DPdK.PW. cbn [outside]. lia.
    - apply M1. unfold W1. cbn [outside]. lia.
  Qed.

  Lemma tw_place : forall ff fp, fresh_frame H LF 2 ff fp ->
    as_FSB H + AFS_HDR <= ff /\ ff + 256 <= as_FSB H + AFS_SIZE /\ ff mod 64 = 0
    /\ as_FSB H + AFS_FLAGS <= fp < as_FSB H + AFS_HDR
    /\ AIMG_TOP <= as_FSB H /\ as_FSB H + AFS_SIZE <= aceil /\ as_FSB H mod 4096 = 0
    /\ (as_FSB H + AFS_SIZE <= ALOWSH_LO \/ AHI_LO <= as_FSB H) /\ aapp (as_FSB H) AFS_SIZE
    /\ sh (as_FSB H) <= sh ff /\ sh ff + 32 <= sh (as_FSB H + AFS_SIZE) /\ 0x800d5000 <= sh ff
    /\ sh ff + 32 <= sh aceil.
  Proof.
    intros ff fp (FFR & FSB_OK & _).
    pose proof FFR as (K1 & K2 & K3 & (K4 & K5) & K6). unfold fsz in K3. change (64 * 2 ^ 2) with 256 in K3.
    pose proof FSB_OK as (B1 & B2 & B3 & B4).
    assert (B4' : as_FSB H + AFS_SIZE <= ALOWSH_LO \/ AHI_LO <= as_FSB H).
    { clear - B4. unfold aapp, aapp_lo, aapp_hi, ALOWSH_LO, AHI_LO, AIMG_TOP in *. destruct B4; [left | right]; lia. }
    assert (SH : sh (as_FSB H) <= sh ff /\ sh ff + 32 <= sh (as_FSB H + AFS_SIZE) /\ 0x800d5000 <= sh ff
                 /\ sh ff + 32 <= sh aceil).
    { clear - K2 K3 B1 B2. unfold sh, ASHADOW_BASE, AFS_HDR, AFS_SIZE, AIMG_TOP in *. Z.div_mod_to_equations. lia. }
    destruct SH as (S1 & S2 & S3 & S4).
    repeat match goal with |- _ /\ _ => split end; try assumption; lia.
  Qed.

  Lemma tw_laws : forall LB ff fp, fresh_frame H LF 2 ff fp ->
    Forall (aclient_write_ok H LB) (TW ff fp) /\ Forall stack0_ok (TW ff fp) /\ Forall aconst_ok (TW ff fp).
  Proof.
    intros LB ff fp FR.
    pose proof (tw_place ff fp FR) as (P1 & P2 & P3 & P4 & P5 & P6 & P7 & P8 & P9 & P10 & P11 & P12 & P13).
    pose proof aceil_facts as ((A1 & A2) & A3 & A4).
    destruct (ah_RFS_range H HHb _ _ RFS0) as [_ FR0].
    assert (DSF : as_FSB H + AFS_HDR <= ds /\ ds + DS_SIZE <= as_FSB H + AFS_SIZE).
    { pose proof DSin as (f & Hf & F1 & F2). pose proof (FR0 f Hf) as (L1 & L2 & L3 & _). clear - F1 F2 L2 L3. lia. }
    assert (SA : ALOWSH_LO <= sh aceil) by (clear - A1; unfold sh, ASHADOW_BASE, ALOWSH_LO in *; Z.div_mod_to_equations; lia).
    unfold TW. split; [|split].
    - repeat apply Forall_cons; try apply Forall_nil; unfold aclient_write_ok; cbn [fst snd].
      + left. clear - CEIL LO. unfold ADS_STACK in *. lia.
      + right; right; right; right; left. clear. unfold AFS_FLAGS, AFS_SIZE. lia.
      + right; right; right; right; left. clear - P4. unfold AFS_FLAGS, AFS_HDR, AFS_SIZE in *. lia.
      + right; right; right; right; left. clear - P1 P2. unfold AFS_HDR in *. lia.
      + right; right; right; right; right; left. clear - P10 P11. lia.
      + right; right; right; right; left. clear - DSF. unfold AFS_HDR in *. lia.
    - repeat apply Forall_cons; try apply Forall_nil; unfold stack0_ok; cbn [fst snd].
      + left. clear - CEIL LO A1. unfold ADS_STACK, AHI_LO in *. lia.
      + clear - P8 SA. unfold AFS_FLAGS, AFS_SIZE in *. destruct P8; [right | left]; lia.
      + clear - P8 P4 SA. unfold AFS_FLAGS, AFS_HDR, AFS_SIZE in *. destruct P8; [right | left]; lia.
      + clear - P8 P1 P2 SA. unfold AFS_HDR in *. destruct P8; [right | left]; lia.
      + right. exact P13.
      + clear - P8 DSF SA. unfold AFS_HDR, AFS_SIZE in *. destruct P8; [right | left]; lia.
    - repeat apply Forall_cons; try apply Forall_nil.
      + apply LbB_DPdK.aconst_ok_hi. clear - CEIL LO A1. unfold ADS_STACK in *. lia.
      + apply (aconst_ok_app (as_FSB H) AFS_SIZE); [exact P9 | clear; lia | clear; unfold AFS_FLAGS, AFS_SIZE; lia].
      + apply (aconst_ok_app (as_FSB H) AFS_SIZE); [exact P9 | clear - P4; unfold AFS_FLAGS in *; lia | clear - P4; unfold AFS_FLAGS, AFS_HDR, AFS_SIZE in *; lia].
      + apply (aconst_ok_app (as_FSB H) AFS_SIZE); [exact P9 | clear - P1; unfold AFS_HDR in *; lia | exact P2].
      + apply LbB_DPdK.aconst_ok_hi. clear - P12. lia.
      + apply (aconst_ok_app (as_FSB H) AFS_SIZE); [exact P9 | clear - DSF; unfold AFS_HDR in *; lia | clear - DSF; lia].
  Qed.

  Lemma tw_out_img : forall ff fp a, fresh_frame H LF 2 ff fp -> aimg_client a -> outside (TW ff fp) a.
  Proof.
    intros ff fp a FR Ha.
    pose proof (tw_place ff fp FR) as (P1 & P2 & P3 & P4 & P5 & P6 & P7 & P8 & P9 & P10 & P11 & P12 & P13).
    pose proof aceil_facts as ((A1 & A2) & A3 & A4).
    pose proof DSO as (O1 & O2 & O3).
    assert (AT : a < AIMG_TOP) by (clear - Ha; unfold aimg_client, AIMG_TOP in *; lia).
    apply LbB_DPdK.outside_of. unfold TW.
    clear - AT P1 P4 P5 P12 O1 A1 CEIL LO.
    unfold ADS_STACK, AFS_HDR, AFS_FLAGS, AIMG_TOP in *.
    repeat (apply Forall_cons; [cbn [fst snd]; lia|]). apply Forall_nil.
  Qed.

  Lemma tw_keep : forall ff fp m', fresh_frame H LF 2 ff fp -> munch (TW ff fp) m0 m' -> wmono asegs m0 m' ->
    stk asegs m' lo spz /\ LINV_P5 m' /\ ACONST m' /\ wr_at asegs m' ds DS_SIZE.
  Proof.
    intros ff fp m' FR MU WM.
    pose proof aceil_facts as ((A1 & A2) & A3 & A4).
    pose proof (bv_unsigned_in_range 64 sp) as R. change (bv_modulus 64) with (2 ^ 64) in R.
    pose proof (tw_laws [] ff fp FR) as (_ & _ & LAC).
    split.
    { eapply stk_transport; [exact STK | exact MU | exact WM |]. intros x Hx. right.
      pose proof STK as (S1 & S2 & S3). destruct (S3 x Hx) as [HV _].
      pose proof (WM (wa x) HV) as HV'.
      assert (HX : AIMG_TOP <= bv_unsigned (wa x)) by (unfold wa; rewrite unsigned_lit by lia; unfold AIMG_TOP; lia).
      rewrite (BakeStackRep.wview_high m' (wa x) HX) in HV'.
      destruct (m' (wa x)) as [b|] eqn:Eb; [exists b; reflexivity | contradiction]. }
    split.
    { eapply LINV_P5_cl; [exact LV0|]. intros a Ha Hc. unfold wa. apply MU. rewrite unsigned_lit by lia.
      exact (tw_out_img ff fp a FR Hc). }
    split; [eapply ACONST_frame; [exact AC0 | exact MU | exact WM | exact LAC]|].
    eapply wr_at_transport; [exact DSW | exact WM].
  Qed.

  Lemma tw_xpres : forall s LB m' ff fp, as_RHEAP H s LB m0 -> munch (TW ff fp) m0 m' -> wmono asegs m0 m' ->
    xpres H LB spz ([(ds, ds + DS_SIZE)] ++ [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + fsz 2); (sh ff, sh ff + fshn 2)])
          m0 m'.
  Proof.
    intros s LB m' ff fp RH MU WM.
    apply (xpres_of_munch H s LB spz _ (TW ff fp) m0 m0 m' HHb RH MU WM).
    unfold TW. change (fsz 2) with 256. change (fshn 2) with 32.
    apply Forall_cons; [left; cbn [fst snd]; clear - CEIL LO; unfold ADS_STACK in *; lia|].
    repeat (apply Forall_cons; [right; intros x Hx; cbn [fst snd app rin_ivs] in *; lia|]).
    apply Forall_nil.
  Qed.

  Lemma pd_sr_of : forall pc s msF mo LB B shi errv,
    evt asegs pdF (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 aw a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                      F (Z_to_bv 64 pc) fc None m0 (seg_rom asegs)) ->
    as_VIS H s msF = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 aw a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                        F (Z_to_bv 64 pc) fc None m0 (seg_rom asegs) ->
    FPSteps.frm_zero fc -> as_RHEAP H s LB m0 -> as_AKREL H s (mkCfg msF mo) -> as_rauxv_ok H m0 B ->
    rw_cells asegs m0 (errno_addr tp) [C4 errv] -> stack0 m0 lo shi ->
    as_SR H (ds_post H LINV_P5 ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc s LB LB LF [(ds, ds + DS_SIZE)] 0 lo B shi
                     m0 mo None (fun LB' m' => Permutation LB' LB /\ ds_repA0 LB' m' ds err 0 [] /\ wr_at asegs m' ds DS_SIZE))
            (mkCfg msF mo).
  Proof using All.
    intros pc s msF mo LB B shi errv HEV VIS FZ RH KR RAUX ERRN S0.
    eapply (ahh_evt_then H HHb pdF _ s msF _ mo KR VIS HEV).
    intros msF' mo' KR' MP' HOK.
    apply (ah_done H HHb).
    destruct HOK as (ff & fp & m1 & FRESH & MUW & WMW & HPP).
    destruct HPP as (t0' & t1' & t2' & a0' & a1' & a2' & a3' & a4' & a5' & a6' & a7' & t3' & t4' & t5' & t6' & m' & E' & MI'
                     & PW' & RFS' & REP').
    destruct PW' as (MUP & WMP).
    pose proof (tw_munch ff fp m1 m' MUW MUP) as MUT.
    assert (WMT : wmono asegs m0 m') by (eapply wmono_trans; [exact WMW | exact WMP]).
    destruct (tw_laws LB ff fp FRESH) as (W1' & W2' & W3').
    destruct (tw_keep ff fp m' FRESH MUT WMT) as (ST' & LV' & AC' & DW').
    destruct (tw_place ff fp FRESH) as (P1 & P2 & P3 & P4 & P5 & P6 & P7 & P8 & AP & S1 & S2 & S3 & S4).
    pose proof p1_ranges as (R1 & R2 & R3). pose proof DSO as (O1 & _).
    unfold ds_post. cbn [cfg_ms cfg_model].
    exists t0', t1', t2', a0', a1', a2', a3', a4', a5', a6', a7', t3', t4', t5', t6', m', errv, s, LB,
           [(as_FSB H, as_FSB H + AFS_FLAGS); (fp, fp + 1); (ff, ff + fsz 2); (sh ff, sh ff + fshn 2)], F, fc.
    split; [exact E'|]. split; [exact FZ|]. split; [intros d Hd; discriminate Hd|].
    split; [exact KR'|]. split; [exact MP'|]. split; [exact MI'|]. split; [exact ST'|].
    split.
    { eapply rw_cells_transport; [exact ERRN | exact MUT | exact WMT |].
      unfold TW. cbn [disjoint_from cells_size csize]. rewrite TP, unsigned_lit by (clear; unfold ATP; lia).
      clear - R1 R2 R3 P1 P2 P4 P5 P6 S3 O1. unfold ATP, AIMG_TOP, AFS_HDR, AFS_FLAGS, ADS_STACK in *. cbn. lia. }
    split; [eapply (ah_rauxv_frame H HHb); [exact RAUX | exact MUT | exact WMT | exact W1']|].
    split; [eapply (ah_RHEAP_frame H HHb); [exact RH | exact MUT | exact WMT | exact W1']|].
    split; [split; [apply Permutation_refl | split; [exact (REP' LB) | exact DW']]|].
    split; [exact (fs_scratch_of_fresh H LF 2 ff fp FRESH)|].
    split; [exact (tw_xpres s LB m' ff fp RH MUT WMT)|].
    split; [exact RFS'|]. split; [exact AC'|].
    split; [eapply stack0_transport; [exact S0 | exact MUT | exact WMT | exact W2']|].
    split; [exact LV'|]. cbn. clear; lia.
  Qed.
End P1.

Theorem pdiag0_okA {HCEIL : HeapCeil} : forall H, asan_rt_hyps_bp H -> pdiag0_stmtA H LINV_P5 ds_repA0.
Proof.
  intros H HHbp ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         F fc msF m mo s LB LF CH lo B shi errv ds p pcons icount err
         PRE Ha0 Ha1 Ha2 HE PPO PPC PIO PIC ICN PC16 DSOB DSW DSIN PCOB PCC DISJ.
  assert (E4 : err = - 4) by exact HE.
  assert (ERR : - 2 ^ 31 <= err < 0) by (rewrite E4; lia).
  destruct PRE as (VIS & FZ & RH & KR & OWN & LBS & LBC & LBL & RAUX & SPB & BB & SP16 & STK & CEIL & LO & ERRN & MI & TP & RA2 & LV
                   & AC & RFS & LFn & S0 & SPS & CHN & PF & CHsp & TRok & COST).
  pose proof DSOB as (DSA & DS8 & DSfs & DS0 & DS47 & DSsp & DSO).
  pose proof PCOB as (PCA & PC8 & PCfs & PC0 & PC47 & PCsp & PCO).
  pose proof (rt_bp_base H HHbp) as HHb.
  destruct (LbB_DCtor.inframe_facts H HHb LF m ds DS_SIZE RFS DSIN ltac:(clear; unfold DS_SIZE; lia) (proj1 DSO))
    as (DSH & DSV & _ & _).
  assert (SPHI : bv_unsigned sp <= AAPP_HI) by (pose proof (stack0_bounds m lo shi S0); lia).
  assert (SPOBJ : forall O n, O = ds /\ n = DS_SIZE \/ O = pcons /\ n = 48 ->
                  O + n <= bv_unsigned sp - ADS_STACK \/ bv_unsigned sp <= O).
  { intros O n [[-> ->] | [-> ->]]; assumption. }
  assert (LFn' : (length LF < AFS_MAXLIVE_BP)%nat) by (unfold DS_FRAMES in LFn; lia).
  pose proof (ah_thr H HHb s LB m RH) as THR.
  clear HE DSOB PCOB.
  eapply pd_sr_of.
  all: try (lazymatch goal with |- as_VIS _ _ _ = _ => eexact VIS end).
  all: try (lazymatch goal with |- evt _ _ _ => eapply pd0_full end).
  all: try (lazymatch goal with |- _ = Z_to_bv 64 _ => eassumption end).
  all: try (lazymatch goal with |- ro_cells _ _ _ _ => eassumption end).
  all: try (lazymatch goal with |- _ mod _ = 0 => fail | |- ?G =>
              let S := type of G in lazymatch S with Prop => eassumption end end).
  all: try (lazymatch goal with |- ?G => let S := type of G in lazymatch S with Prop => eassumption end end).
  all: eassumption.
Qed.
Theorem pdiagE_okA {HCEIL : HeapCeil} : forall H, asan_rt_hyps_bp H -> pdiagE_stmtA H LINV_P5 ds_repA0.
Proof.
  intros H HHbp ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
         F fc msF m mo s LB LF CH lo B shi errv ds p pcons icount err
         PRE Ha0 Ha1 Ha2 HE PPO PPC PIO PIC ICN PC16 DSOB DSW DSIN PCOB PCC DISJ.
  assert (ERR : - 2 ^ 31 <= err < 0) by exact HE.
  destruct PRE as (VIS & FZ & RH & KR & OWN & LBS & LBC & LBL & RAUX & SPB & BB & SP16 & STK & CEIL & LO & ERRN & MI & TP & RA2 & LV
                   & AC & RFS & LFn & S0 & SPS & CHN & PF & CHsp & TRok & COST).
  pose proof DSOB as (DSA & DS8 & DSfs & DS0 & DS47 & DSsp & DSO).
  pose proof PCOB as (PCA & PC8 & PCfs & PC0 & PC47 & PCsp & PCO).
  pose proof (rt_bp_base H HHbp) as HHb.
  destruct (LbB_DCtor.inframe_facts H HHb LF m ds DS_SIZE RFS DSIN ltac:(clear; unfold DS_SIZE; lia) (proj1 DSO))
    as (DSH & DSV & _ & _).
  assert (SPHI : bv_unsigned sp <= AAPP_HI) by (pose proof (stack0_bounds m lo shi S0); lia).
  assert (SPOBJ : forall O n, O = ds /\ n = DS_SIZE \/ O = pcons /\ n = 48 ->
                  O + n <= bv_unsigned sp - ADS_STACK \/ bv_unsigned sp <= O).
  { intros O n [[-> ->] | [-> ->]]; assumption. }
  assert (LFn' : (length LF < AFS_MAXLIVE_BP)%nat) by (unfold DS_FRAMES in LFn; lia).
  pose proof (ah_thr H HHb s LB m RH) as THR.
  clear HE DSOB PCOB.
  eapply pd_sr_of.
  all: try (lazymatch goal with |- as_VIS _ _ _ = _ => eexact VIS end).
  all: try (lazymatch goal with |- evt _ _ _ => eapply pdE_full end).
  all: try (lazymatch goal with |- _ = Z_to_bv 64 _ => eassumption end).
  all: try (lazymatch goal with |- ro_cells _ _ _ _ => eassumption end).
  all: try (lazymatch goal with |- _ mod _ = 0 => fail | |- ?G =>
              let S := type of G in lazymatch S with Prop => eassumption end end).
  all: try (lazymatch goal with |- ?G => let S := type of G in lazymatch S with Prop => eassumption end end).
  all: eassumption.
Qed.
